  // --- more passkeys, one-time codes for another device (#95) ---
  '1 passkey': '1 passkey',
  'A one-time code lets your phone or another computer sign in with a passkey of its own.': 'En engångskod låter din telefon eller en annan dator logga in med en egen passkey.',
  'Add a passkey': 'Lägg till en passkey',
  'Add another device': 'Lägg till en annan enhet',
  'Add this device': 'Lägg till den här enheten',
  'Added {0}': '{0} tillagd',
  'Code from your other device': 'Kod från din andra enhet',
  'Confirm with a passkey': 'Bekräfta med en passkey',
  'Confirmed. Now create the new passkey; your browser will ask where to keep it.': 'Bekräftat. Skapa nu den nya passkeyn; webbläsaren frågar var den ska sparas.',
  'Copy link': 'Kopiera länk',
  'Create a passkey on this device for the profile “{0}”. It signs you in here from now on.': 'Skapa en passkey på den här enheten för profilen ”{0}”. Den loggar in dig här från och med nu.',
  'Each one signs in to this profile from the device or password manager that keeps it. Tap one to rename or remove it.': 'Varje passkey loggar in på den här profilen från enheten eller lösenordshanteraren som sparar den. Tryck på en för att byta namn eller ta bort den.',
  'Enter the code from your other device.': 'Ange koden från din andra enhet.',
  'For this device, a security key, a password manager, or your phone through the browser’s own QR code. First confirm that it is you.': 'För den här enheten, en säkerhetsnyckel, en lösenordshanterare eller din telefon via webbläsarens egen QR-kod. Bekräfta först att det är du.',
  'It can no longer sign in to this profile. A device already signed in with it stays signed in. If it was lost, use Sign out everywhere.': 'Den kan inte längre logga in på den här profilen. En enhet som redan är inloggad med den förblir inloggad. Om den har tappats bort, använd Logga ut överallt.',
  'It is your only way in, so it cannot be removed until there is another.': 'Det är ditt enda sätt att komma in, så den kan inte tas bort förrän det finns en till.',
  'Last used {0}': 'Senast använd {0}',
  'Make a new code': 'Skapa en ny kod',
  'Name, e.g. Work laptop': 'Namn, t.ex. Jobbdator',
  'None yet. Add one and sign in without your password.': 'Inga än. Lägg till en och logga in utan lösenord.',
  'Passkey added': 'Passkey tillagd',
  'Passkey removed': 'Passkey borttagen',
  'Passkey {0}': 'Passkey {0}',
