  'Remove passkey': 'Ta bort passkey',
  'Remove this passkey?': 'Ta bort den här passkeyn?',
  'Scan this with the other device, or open openGym there and enter the code on the sign-in screen. It works once, for {0} minutes.': 'Skanna den med den andra enheten, eller öppna openGym där och ange koden på inloggningsskärmen. Den fungerar en gång, i {0} minuter.',
  'That code is wrong, already used or expired. Make a new one on your other device.': 'Koden är fel, redan använd eller har gått ut. Skapa en ny på din andra enhet.',
  'This browser cannot confirm with your passkey. Do this on a device that holds one.': 'Den här webbläsaren kan inte bekräfta med din passkey. Gör det på en enhet som har en.',
  'First confirm that it is you.': 'Bekräfta först att det är du.',
  'This profile has no passkey, and this server does not take passwords, so nothing here can confirm that it is you. Ask your admin.': 'Den här profilen har ingen passkey och servern tar inte emot lösenord, så inget här kan bekräfta att det är du. Kontakta din admin.',
  'This browser cannot create passkeys, so it cannot be added with a code. Open the link in a browser that can.': 'Den här webbläsaren kan inte skapa passkeys, så den kan inte läggas till med en kod. Öppna länken i en webbläsare som kan.',
  'This browser is signed in as “{0}”. Adding it to “{1}” signs “{0}” out here.': 'Den här webbläsaren är inloggad som ”{0}”. Om du lägger till den i ”{1}” loggas ”{0}” ut här.',
  'This code is for a different profile that is also called “{0}”, not the one this browser is signed in as. Adding it there signs yours out here.': 'Den här koden gäller en annan profil som också heter ”{0}”, inte den som webbläsaren är inloggad som. Om du lägger till den där loggas din ut här.',
  'Only continue if this code comes from a device of your own. This browser is then signed in to “{0}”, and what you log here goes to that profile.': 'Fortsätt bara om koden kommer från en av dina egna enheter. Webbläsaren loggas då in på ”{0}”, och det du loggar här hamnar i den profilen.',
