  'Deletes your plan, workouts, body weight, photos and videos on this device. This cannot be undone.': 'Tar bort din plan, dina pass, din kroppsvikt, dina foton och videor på den här enheten. Det går inte att ångra.',
  'Deletes your plan, workouts, body weight, photos and videos from your profile on this server and on every signed-in device. This cannot be undone.': 'Tar bort din plan, dina pass, din kroppsvikt, dina foton och videor från din profil på servern och på alla inloggade enheter. Det går inte att ångra.',
  'Sync failed: the server refused the upload as too large. Your changes have not reached the server.': 'Synkningen misslyckades: servern avvisade uppladdningen som för stor. Dina ändringar har inte nått servern.',
  'This device is out of storage: the change is not saved on it. Signed in, it still goes to the server.': 'Den här enheten har slut på lagringsutrymme: ändringen sparas inte här. När du är inloggad skickas den ändå till servern.',
