  'Add time': 'Öka tiden',
  'Targets stay where you set them.': 'Målen stannar där du satt dem.',
  'Hit every rep in every set and the weight goes up. Repeated misses trigger a deload.': 'Klara varje rep i varje set så höjs vikten. Upprepade missar ger en avlastning.',
  'Two straight sets plus a final set taken to failure. Beat the target on that set and the weight goes up (twice as much if you double the reps). One failure resets 10 %.': 'Två vanliga set plus ett sista set till failure. Slå målet på det setet så höjs vikten (dubbelt så mycket om du dubblar repsen). En miss sänker med 10 %.',
  'Work up through a rep range at the same weight. Reach the top of the range in every set and the weight goes up, reps back to the bottom.': 'Arbeta dig upp genom ett repintervall med samma vikt. Nå toppen av intervallet i varje set så höjs vikten och repsen går tillbaka till botten.',
  'Hold every set for the full duration and the target goes up.': 'Håll varje set hela tiden så höjs målet.',
  'Nothing logged yet, so this session sets the baseline.': 'Inget loggat än, så det här passet sätter utgångsläget.',
  'Held every set for the full time. Target goes up by {0}s.': 'Höll varje set hela tiden. Målet höjs med {0} s.',
  'Short {0} sessions in a row. Back off to {1}s and build up again.': 'För korta {0} pass i rad. Backa till {1} s och bygg upp igen.',
  'Came up short last time. Same target again.': 'Kom inte hela vägen förra gången. Samma mål igen.',
  'Top of the rep range in every set. {0} {1} more, back to {2} reps.': 'Toppen av repintervallet i varje set. {0} {1} mer, tillbaka till {2} reps.',
