  'Every rep last time. {0} {1} more.': 'Varje rep förra gången. {0} {1} mer.',
  'Every rep last time. {0} {1} less help.': 'Varje rep förra gången. {0} {1} mindre hjälp.',
  'Top of the rep range in every set. {0} {1} less help, back to {2} reps.': 'Toppen av repintervallet i varje set. {0} {1} mindre hjälp, tillbaka till {2} reps.',
  'Missed reps. {0} {1} of help while you build back up.': 'Missade reps. {0} {1} hjälp medan du bygger upp igen.',
  'Stuck for {0} sessions. Back to {1} {2} of help, then build up again.': 'Fast i {0} pass. Tillbaka till {1} {2} hjälp, bygg sedan upp igen.',
  'Missed reps {0} sessions running. Reset to {1} {2} and work back up.': 'Missade reps {0} pass i rad. Återställ till {1} {2} och arbeta dig upp igen.',
