  'The highlighted row is where most working sets land. Sets you have already logged keep their own scale, and nothing else reads the value, so progression and estimated 1RM are unaffected.': 'Den markerade raden är där de flesta arbetsset hamnar. Set du redan loggat behåller sin egen skala, och inget annat läser värdet, så progression och uppskattat 1RM påverkas inte.',
