  'Anything to work around?': 'Något att ta hänsyn till?',
  'Injuries, joints that complain, movements you cannot do, or practical limits like training at 6am in a flat.': 'Skador, leder som klagar, rörelser du inte kan göra eller praktiska begränsningar som att träna kl. 6 i en lägenhet.',
