  'The Coach needs your go-ahead first.': 'Coachen behöver ditt godkännande först.',
  'The key is stored in this phone’s secure storage and never leaves it except to call the provider.': 'Nyckeln lagras i telefonens säkra lagring och lämnar den aldrig, utom för att anropa leverantören.',
