  // --- AI Coach chat ---
  'A local model can take longer.': 'En lokal modell kan ta längre tid.',
  'All optional. The more the Coach knows, the less it guesses.': 'Allt är valfritt. Ju mer coachen vet, desto mindre gissar den.',
