  'Experience': 'Erfarenhet',
  'Goal, days, equipment, limits': 'Mål, dagar, utrustning, begränsningar',
  'Have a look at my training and tell me what you would change.': 'Titta på min träning och berätta vad du skulle ändra.',
  'Here is what I am working with:': 'Det här utgår jag från:',
  'Hi, I’m your Coach. I build your plan from your answers and adjust it from what you actually log. Nothing changes until you say so.': 'Hej, jag är din coach. Jag bygger din plan utifrån dina svar och justerar den efter det du faktiskt loggar. Inget ändras förrän du säger till.',
  'I looked through everything and there is nothing I would change right now. Keep it up, and ask me again after a few more sessions.': 'Jag har gått igenom allt och det finns inget jag skulle ändra just nu. Fortsätt så, och fråga mig igen efter några pass till.',
  'I understand, let’s go': 'Jag förstår, nu kör vi',
  'Imported! {0} routines are in your plan and your week is set. See you at the next session.': 'Importerat! {0} rutiner finns i din plan och din vecka är inställd. Vi ses nästa pass.',
  'Imported! {0} routines are in your plan. Your week is unchanged; schedule them whenever you like.': 'Importerat! {0} rutiner finns i din plan. Din vecka är oförändrad; schemalägg dem när du vill.',
  'It designs your plan from a few answers and adjusts it from what you actually log. It never changes anything without your say-so, and you can undo every change.': 'Den utformar din plan utifrån några svar och justerar den efter det du faktiskt loggar. Den ändrar aldrig något utan ditt godkännande, och du kan ångra varje ändring.',
  'Routines, exercises, sets and reps, your weekly schedule and progression settings.': 'Rutiner, övningar, set och reps, ditt veckoschema och dina progressionsinställningar.',
  'Your logged training': 'Din loggade träning',
  'Sets you logged in the review window: weights, reps, times, effort ratings, how long sessions took, and your session notes.': 'Set du loggat under genomgångsperioden: vikter, reps, tider, ansträngningsbedömningar, hur lång tid passen tog och dina passanteckningar.',
  'Weigh-ins from the same window, and your goal weight if you set one.': 'Vägningar från samma period, och din målvikt om du har satt en.',
  'What you tell the Coach': 'Det du berättar för coachen',
  'Your intake answers, including any limitations or injuries you describe.': 'Dina svar från uppstarten, inklusive begränsningar eller skador du beskriver.',
  'A few preferences': 'Några inställningar',
  'Your unit, your language and which effort scale you log.': 'Din enhet, ditt språk och vilken ansträngningsskala du loggar med.',
