  // --- demo build (v1.3.7) ---
  'A pull for every press, so the shoulders stay balanced.': 'Ett drag för varje press, så att axlarna hålls i balans.',
  'A two-day rotation across three sessions a week, built around the equipment you listed. Compounds first, one pull for every press, and enough overlap between the days that nothing goes two weeks without being trained.': 'En tvådagarsrotation över tre pass i veckan, byggd kring utrustningen du angav. Basövningar först, ett drag för varje press och tillräcklig överlappning mellan dagarna för att inget ska gå två veckor utan träning.',
  'Based on the training already in this demo profile.': 'Baserat på träningen som redan finns i den här demoprofilen.',
  'Body weight has been flat for four weeks while the goal is to gain. That’s a kitchen problem, not a training one. The plan isn’t what’s holding it back.': 'Kroppsvikten har legat still i fyra veckor medan målet är att gå upp. Det är ett köksproblem, inte ett träningsproblem. Det är inte planen som håller tillbaka.',
