  'Demo data reset': 'Demodata återställd',
  'Direct arm work, since you asked for it.': 'Direkt armträning, eftersom du bad om det.',
  'Every top set on this one came in at RPE 9.5 or above for three sessions and the weight has not moved. Swapping the movement for four weeks usually breaks that stall faster than grinding the same one.': 'Varje toppset i den här låg på RPE 9,5 eller högre i tre pass och vikten har inte rört sig. Att byta rörelse i fyra veckor bryter oftast en sådan platå snabbare än att nöta på samma.',
  'Example data, stored only in this browser. Go wild and change anything you like.': 'Exempeldata, sparad bara i den här webbläsaren. Ändra fritt på vad du vill.',
  'Full body A': 'Helkropp A',
  'Full body B': 'Helkropp B',
  'Horizontal pressing, the other half of the session.': 'Horisontell press, den andra halvan av passet.',
  'Live demo. Everything stays in this browser.': 'Livedemo. Allt stannar i den här webbläsaren.',
  'No training history yet, so starting conservatively.': 'Ingen träningshistorik än, så vi börjar försiktigt.',
  'Passkey sign-in, sync across your devices, your own data.': 'Inloggning med passkey, synk mellan dina enheter, din egen data.',
  'Puts the example plan, workouts and weigh-ins back the way they started.': 'Återställer exempelplanen, passen och vägningarna till hur de var från början.',
  'Reset': 'Återställ',
  'Reset demo data': 'Återställ demodata',
  'Reset demo data?': 'Återställa demodata?',
  'Revised as you asked. Everything you did not question is exactly as it was.': 'Ändrad enligt din önskan. Allt du inte ifrågasatte är exakt som förut.',
  'Same pattern, higher reps than day A.': 'Samma mönster, fler reps än dag A.',
  'Self-host it in a minute →': 'Självhosta den på en minut →',
  'Self-host openGym': 'Självhosta openGym',
  'Sessions have been running about fifteen minutes over. This is the accessory with the least to lose from one set fewer.': 'Passen har dragit över med ungefär femton minuter. Det här är den kompletterande övningen som förlorar minst på ett set färre.',
  'Start the demo': 'Starta demon',
  'The main lower-body driver, where most of the strength comes from.': 'Den viktigaste drivkraften för underkroppen, där det mesta av styrkan kommer ifrån.',
  'The same patterns, different variations: enough overlap to progress, enough difference to stay fresh.': 'Samma mönster, andra varianter: tillräcklig överlappning för att göra framsteg, tillräcklig skillnad för att hålla det fräscht.',
  'The two big lower-body and pressing patterns first, while you are fresh.': 'De två stora mönstren för underkropp och press först, medan du är pigg.',
  'This demo runs entirely in your browser on example data. Nothing is sent anywhere. Passkey sign-in and sync across your devices come with the openGym server, which you get by self-hosting it.': 'Den här demon körs helt i din webbläsare med exempeldata. Inget skickas någonstans. Inloggning med passkey och synk mellan dina enheter ingår i openGym-servern, som du får genom att självhosta den.',
  'Three things worth changing, and one worth knowing about. Everything else is working: the squat and the pulls are both progressing on schedule.': 'Tre saker värda att ändra och en värd att känna till. Allt annat fungerar: knäböjen och dragen går båda framåt enligt plan.',
  'Vertical pressing.': 'Vertikal press.',
  'You have moved this session to Saturday three weeks running. Better the plan says so than that you keep overriding it.': 'Du har flyttat det här passet till lördag tre veckor i rad. Bättre att planen säger det än att du fortsätter åsidosätta den.',
