  'This folder can’t be used for backups.': 'Den här mappen kan inte användas för backuper.',
  'openGym can no longer write to “{0}”, so copies go to Documents/openGym again. Choose the folder again to switch back.': 'openGym kan inte längre skriva till ”{0}”, så kopiorna hamnar i Documents/openGym igen. Välj mappen igen för att byta tillbaka.',
  'openGym can no longer write to the chosen folder, so copies go to Documents/openGym again. Choose the folder again to switch back.': 'openGym kan inte längre skriva till den valda mappen, så kopiorna hamnar i Documents/openGym igen. Välj mappen igen för att byta tillbaka.',
  // --- missed-workout nudge (lib/nudge.js; the push copy is mirrored in api/nudge-copy.js) ---
  'Nudge me when I skip a planned workout': 'Påminn mig när jag hoppar över ett planerat pass',
  'Nudge tone': 'Ton i påminnelsen',
  'Friendly': 'Vänlig',
  'Guilt trip': 'Dåligt samvete',
  'Drill sergeant': 'Drillsergeant',
  'One nudge in the evening of a planned day with nothing logged, between 20:00 and 21:30. After 3 missed days in a row it goes quiet until your next workout.': 'En påminnelse på kvällen en planerad dag utan något loggat, mellan 20:00 och 21:30. Efter 3 missade dagar i rad blir det tyst tills ditt nästa pass.',
  'Logged a workout on another device? Before the nudge goes out, the phone checks with your server whenever it lets the app run in the background. Opening the app always catches up.': 'Loggat ett pass på en annan enhet? Innan påminnelsen går ut frågar telefonen din server, när den låter appen köra i bakgrunden. Att öppna appen kommer alltid i fatt.',
  'Everything okay?': 'Är allt okej?',
  '{0} is still waiting. What’s up?': '{0} väntar fortfarande. Hur är läget?',
  'No {0} today? Even a short session tomorrow counts.': 'Inget {0} idag? Även ett kort pass i morgon räknas.',
  'Rough day? {0} will keep. Tomorrow is a fresh start.': 'Tuff dag? {0} kan vänta. I morgon är en ny dag.',
  'Hey, {0} didn’t happen today. All good?': 'Hej, {0} blev inte av idag. Allt bra?',
  'I miss you': 'Jag saknar dig',
  '{0} waited by the door all evening. For you.': '{0} väntade vid dörren hela kvällen. På dig.',
  'The barbell asked about you today. I didn’t know what to say.': 'Skivstången frågade efter dig idag. Jag visste inte vad jag skulle säga.',
  'Was it something I said? {0} misses you.': 'Var det något jag sa? {0} saknar dig.',
  'I saved you a spot on the bench. It’s still empty.': 'Jag höll en plats på bänken åt dig. Den är fortfarande tom.',
  'Attention, recruit!': 'Givakt, rekryt!',
  'Your gains are packing their bags. {0} tomorrow, no excuses!': 'Dina gains packar väskorna. {0} i morgon, inga ursäkter!',
  '{0} doesn’t do itself, recruit. Move it!': '{0} gör inte sig självt, rekryt. Sätt fart!',
  'Excuses don’t lift weights. Report for {0} tomorrow!': 'Ursäkter lyfter inga vikter. Anmäl dig till {0} i morgon!',
  'Your muscles filed a missing-person report. Show up for {0}!': 'Dina muskler har anmält dig försvunnen. Infinn dig till {0}!',
  'That address answers, but it isn’t an openGym server. Check the URL.': 'Adressen svarar, men det är inte en openGym-server. Kontrollera URL:en.',
  'That address answers, but a login page or proxy rule replied instead of openGym. Let /api/ through to openGym unchanged. See “Phone app and CORS” in docs/SELF_HOSTING.md.': 'Adressen svarar, men en inloggningssida eller proxyregel svarade i stället för openGym. Släpp igenom /api/ till openGym oförändrat. Se ”Phone app and CORS” i docs/SELF_HOSTING.md.',
  'Switch sides': 'Byt sida',
  'Saves a dated copy to “{0}” after finishing a workout or editing a routine, and keeps the newest {1}.': 'Sparar en daterad kopia i ”{0}” när du avslutat ett pass eller ändrat en rutin, och behåller de {1} senaste.',
  'Saves a dated copy to the folder you chose after finishing a workout or editing a routine, and keeps the newest {0}.': 'Sparar en daterad kopia i mappen du valde när du avslutat ett pass eller ändrat en rutin, och behåller de {0} senaste.',
