  'Effort per set is off. Turn it on in Settings → Workout to keep rating.': 'Ansträngning per set är avstängt. Slå på det i Inställningar → Pass för att fortsätta bedöma.',
  'Enter the code your other device shows under Settings → Account → Add another device. This device then gets a passkey of its own.': 'Ange koden som din andra enhet visar under Inställningar → Konto → Lägg till en annan enhet. Den här enheten får då en egen passkey.',
  'Open Settings → Account → “Pair the mobile app” on the openGym site you’re already signed into, then enter its address and the code shown there.': 'Öppna Inställningar → Konto → ”Parkoppla mobilappen” på openGym-sidan där du redan är inloggad, och ange sedan dess adress och koden som visas där.',
  'Open Settings → Account → “Pair the mobile app” on your openGym site in a browser and enter the new code shown there. What this phone kept is merged into your account.': 'Öppna Inställningar → Konto → ”Parkoppla mobilappen” på din openGym-sida i en webbläsare och ange den nya koden som visas där. Det som telefonen sparat slås ihop med ditt konto.',
