  'What the bars at your gym weigh. Every exercise with that bar counts plates from it, unless you gave the exercise its own. Logged weights stay totals.': 'Vad stängerna på ditt gym väger. Varje övning med den stången räknar viktskivor utifrån den, om du inte gett övningen en egen. Loggade vikter förblir totalvikter.',
  'Most lifts in the library use “{0}”, a few use “{1}”. A short bar for all of them means setting both.': 'De flesta lyft i biblioteket använder ”{0}”, några använder ”{1}”. En kort stång för alla betyder att du ställer in båda.',
