  // --- app tour (components/Tour.jsx) ---
  "A one-minute walk around the app": "En minuts promenad i appen",
  "A practice workout": "Ett övningspass",
  "Backups, imports and syncing with your own server.": "Säkerhetskopior, importer och synk med din egen server.",
  "Body map": "Kroppskarta",
  "Catch your breath": "Andas ut",
  "Done with a set? Tick it. Go on, try it.": "Klar med ett set? Bocka av. Kör, testa.",
  "Filter it down": "Smalna av",
  "Find any exercise": "Hitta vilken övning som helst",
  "Finish line": "Mållinjen",
  "Finish saves the session and moves your weights along. This practice one just quietly disappears.": "Avsluta sparar passet och för dina vikter framåt. Det här övningspasset försvinner bara tyst.",
  "Finish the tour?": "Gå klart rundturen?",
  "Finish your workout first, then the tour is all yours.": "Avsluta ditt pass först, sen är rundturen din.",
  "Kilos or pounds, and the language you like best.": "Kilo eller pund, och det språk du gillar mest.",
  "Let’s go": "Nu kör vi",
  "Make it yours": "Gör den till din",
  "Muscles at a glance": "Musklerna i en blick",
  "Narrow the list by body part, type or the equipment you have.": "Smalna av listan efter kroppsdel, typ eller utrustningen du har.",
  "No thanks": "Nej tack",
  "Pick an exercise to see its best sets, estimated max and where it’s heading.": "Välj en övning och se bästa set, uppskattat max och vart det är på väg.",
  "Pointing at: {0}": "Pekar på: {0}",
  "Practice run": "Övningspass",
  "Programmes and sharing": "Program och delning",
  "Programmes, starter plans and sharing a plan with a friend live behind this button.": "Program, startplaner och att dela en plan med en kompis finns bakom den här knappen.",
  "Records": "Rekord",
  "Schedule says when, Routines says what. Build your own or grab a starter plan.": "Schema säger när, Rutiner säger vad. Bygg egna eller ta en startplan.",
  "Search thousands of exercises in your language. Star your favourites and they float to the top.": "Tusentals övningar på ditt språk. Stjärnmärk favoriterna så hamnar de överst.",
  "See which muscles got the work and which still need rest. Tap one for details.": "Se vilka muskler som jobbat och vilka som behöver vila. Tryck på en för detaljer.",
  "Show me": "Visa mig",
  "Show the tour again": "Visa rundturen igen",
  "Skip tour": "Hoppa över rundturen",
  "Step {0} of {1}": "Steg {0} av {1}",
  "Swipe a set": "Svep ett set",
  "Swipe a set sideways to copy or remove it. Its number opens even more.": "Svep ett set åt sidan för att kopiera eller ta bort det. Numret öppnar ännu mer.",
  "The big Start button": "Den stora Starta-knappen",
  "The little body shows what each day works, so leg day can’t hide.": "Den lilla kroppen visar vad varje dag tränar, så bendagen kan inte gömma sig.",
  "The rest timer starts by itself. Add time, or skip it if you feel heroic.": "Vilan startar av sig själv. Lägg till tid, eller hoppa över om du känner dig hjältemodig.",
  "The ⋯ menu": "Menyn ⋯",
  "Theme, accent colour and what Home shows.": "Tema, accentfärg och vad Hem visar.",
  "This one is pretend, nothing gets saved. Each row is a set: weight, then reps. Tap a number to change it.": "Det här är på låtsas, inget sparas. Varje rad är ett set: vikt, sen reps. Tryck på en siffra för att ändra den.",
  "Tick it off": "Bocka av",
  "Today at a glance": "Idag i korthet",
  "Today’s session lives here. One tap and you’re lifting. On a rest day it says so, no guilt trip.": "Dagens pass finns här. Ett tryck och du lyfter. På en vilodag står det det, helt utan dåligt samvete.",
  "Train on fixed weekdays, or run your routines in a loop where the next one waits for you.": "Träna på fasta veckodagar, eller kör dina rutiner i en loop där nästa väntar på dig.",
  "Want a 1-minute tour?": "Vill du ha en rundtur på 1 minut?",
  "Week or rotation": "Vecka eller rotation",
  "We’ll point at the good bits on the real screens. Bail out anytime.": "Vi pekar ut det bästa på de riktiga skärmarna. Hoppa av när du vill.",
  "Workout settings, layouts, notes and extra exercises hide in here.": "Passinställningar, layouter, anteckningar och fler övningar gömmer sig här.",
  "Workouts, streaks and everything you’ve lifted. It fills up as you train.": "Pass, sviter och allt du har lyft. Fylls på när du tränar.",
  "You stopped halfway. Want to see the rest?": "Du slutade halvvägs. Vill du se resten?",
  "Your data, your backups": "Din data, dina säkerhetskopior",
  "Your progress": "Dina framsteg",
  "Your routines": "Dina rutiner",
  "You’re set": "Du är redo",
