  'Pick a day': 'Välj dag',
  'With pictures': 'Med bilder',
  'A small picture next to each exercise, like a plan from the gym.': 'En liten bild bredvid varje övning, som ett program från gymmet.',
  // --- Settings → Integrations (1.4.4) ---
  "This one lives in the openGym phone app: Apple Health on iPhone, Health Connect on Android.": "Det här bor i openGym-appen på mobilen: Apple Health på iPhone, Health Connect på Android.",
  "Webhooks are sent by your own openGym server, so they need one. Connect this device to it in Account.": "Webhooks skickas av din egen openGym-server, så det krävs en. Koppla den här enheten under Konto.",
  "Webhooks are off on this server. Add INTEGRATIONS=webhook to its .env and restart it.": "Webhooks är avstängda på den här servern. Lägg till INTEGRATIONS=webhook i dess .env och starta om den.",
  "The MCP server runs next to your own openGym server and reads your data there.": "MCP-servern körs bredvid din egen openGym-server och läser dina data där.",
  "Only what you switch on talks to anything. The rest stays out of your way.": "Bara det du slår på pratar med något. Resten håller sig ur vägen.",
  "Could not reach your server": "Kunde inte nå din server",
  "Tap to try again": "Tryck för att försöka igen",
  "Disconnect {0}?": "Koppla från {0}?",
  "openGym stops writing and reading. What it already wrote can stay there as your data, or go.": "openGym slutar skriva och läsa. Det som redan skrivits kan stanna som dina data, eller försvinna.",
  "Works with": "Fungerar med",
  "No extra connection needed: they write to {0}, and openGym reads from there.": "Ingen extra koppling behövs: de skriver till {0}, och openGym läser därifrån.",
  "No extra connection needed: they write to Apple Health or Health Connect, and the openGym phone app reads from there.": "Ingen extra koppling behövs: de skriver till Apple Health eller Health Connect, och openGym-appen på mobilen läser därifrån.",
  "{0} has no direct line to openGym, and it does not need one.": "{0} har ingen direktlinje till openGym, och behöver ingen.",
  "How it gets here": "Hur det kommer hit",
  "{0} saves to Apple Health on iPhone or Health Connect on Android. openGym reads from there.": "{0} sparar till Apple Health på iPhone eller Health Connect på Android. openGym läser därifrån.",
  "What openGym reads": "Vad openGym läser",
  "What it does not do": "Vad den inte gör",
  "Workouts logged in openGym go to the health store, not back into {0} itself.": "Pass som loggas i openGym hamnar i hälsolagret, inte tillbaka i {0}.",
  "Set up {0}": "Ställ in {0}",
  "Install the openGym app on your phone to use this.": "Installera openGym-appen på mobilen för att använda det här.",
  "How to set it up": "Så ställer du in det",
  "What it does": "Vad den gör",
  "Last sync": "Senaste synk",
  "Not yet": "Inte än",
  "Permission withdrawn": "Behörighet återkallad",
  "openGym can no longer reach it.": "openGym kommer inte åt den längre.",
  "Retry": "Försök igen",
