  "Head back to Home first. Tap it.": "Gå tillbaka till Hem först. Tryck på det.",
  "Health apps": "Hälsoappar",
  "Here’s the pretend one. Tap it.": "Här är låtsaspasset. Tryck på det.",
  "Home shows it on its day and Start opens it. Change it any time right here.": "Hem visar den på dess dag och Starta öppnar den. Ändra den när du vill, precis här.",
  "It starts today’s plan, or lets you pick something else. Tap it for a practice run.": "Den startar dagens plan, eller låter dig välja något annat. Tryck för en provtur.",
  "Its own page": "En egen sida",
  "It’s the first row of the list. Tap it.": "Det är första raden i listan. Tryck på den.",
  "Log a past workout with its own date and time. It counts like any other.": "Logga ett tidigare pass med eget datum och egen tid. Det räknas som vilket annat som helst.",
  "Measurements and photos": "Mått och foton",
  "Missing one? Make it. It works like any other: routines, workouts, records, the body map, backups and sync. Nothing is created until you tap Create.": "Saknas en? Gör den. Den fungerar som alla andra: rutiner, pass, rekord, kroppskartan, backuper och synk. Inget skapas förrän du trycker på Skapa övning.",
  "Moving in?": "Flyttar du in?",
  "Name a routine, add exercises, give it a day": "Namnge en rutin, lägg till övningar, ge den en dag",
  "Name it": "Namnge den",
  "Name, muscles, equipment and a photo": "Namn, muskler, utrustning och en bild",
  "New routines start on the Routines side. Tap Routines.": "Nya rutiner börjar på sidan Rutiner. Tryck på Rutiner.",
  "Notes": "Anteckningar",
  "Now give it a day. Tap back to Plan.": "Ge den nu en dag. Tryck tillbaka till Plan.",
  "Now your workouts": "Nu dina pass",
