  "One file with everything. Keep it somewhere safe, Import backup brings it back.": "En fil med allt. Förvara den säkert, Importera backup tar tillbaka allt.",
  "One more": "En till",
  "Open a check-in to change or delete it. Progress photos work the same way.": "Öppna en mätning för att ändra eller ta bort den. Framstegsfoton fungerar likadant.",
  "Open a workout": "Öppna ett pass",
  "Optional: your own picture or clip of the setup. Handy for that one weird machine.": "Valfritt: en egen bild eller video av uppställningen. Smidigt för den där enda konstiga maskinen.",
  "Pick a backup file and it’s all back.": "Välj en backupfil så är allt tillbaka.",
  "Pick one. Muscle groups are optional, but they feed the body map and muscle balance.": "Välj en. Muskelgrupper är valfria, men de matar kroppskartan och muskelbalansen.",
  "Pick your exercises": "Välj dina övningar",
  "Practice copy gone": "Övningskopian är borta",
  "Practice session": "Övningspass",
  "Push Day, Legs, Monday Misery. Tap the name and type your own.": "Pushdag, Ben, Måndagsmisär. Tryck på namnet och skriv ditt eget.",
  "Reopens it: sets, weights, reps, exercises. Nothing changes until you tap Save.": "Öppnar det igen: set, vikter, reps, övningar. Inget ändras förrän du trycker på Spara.",
  "Restore a backup": "Återställ en backup",
  "Routine name": "Rutinens namn",
  "Routines are made in Plan. Tap it.": "Rutiner skapas i Plan. Tryck på den.",
  "Save plan": "Spara plan",
  "Save your plan?": "Spara din plan?",
  "Saved!": "Sparat!",
  "Search finds your exercises like any other, and they go into routines and workouts the same way.": "Sökningen hittar dina övningar precis som alla andra, och de hamnar i rutiner och pass på samma sätt.",
  "Settings are on Home": "Inställningarna finns på Hem",
  "Share weigh-ins and workouts with the phone’s health app.": "Dela vägningar och pass med telefonens hälsoapp.",
  "So the equipment filter and your gym profiles know about it.": "Så att utrustningsfiltret och dina gymprofiler känner till den.",
  "Spreadsheet": "Kalkylark",
  "Strong, Hevy, FitNotes, GymMane or Apple Health body weight: import their export here.": "Strong, Hevy, FitNotes, GymMane eller kroppsvikt från Apple Health: importera deras export här.",
  "Syncing lives under your account. Tap back to Settings.": "Synk bor under ditt konto. Tryck tillbaka till Inställningar.",
  "Syncing your devices through your own openGym server lives under your account. No server? Everything still works on this device.": "Synk av dina enheter via din egen openGym-server bor under ditt konto. Ingen server? Allt fungerar ändå på den här enheten.",
  "Tap Add and pick your new routine. The loop runs in that order.": "Tryck på Lägg till och välj din nya rutin. Loopen går i den ordningen.",
  "Tap Add exercise to pick what goes in.": "Tryck på Lägg till övning för att välja vad som ska med.",
  "Tap All weigh-ins.": "Tryck på Alla vägningar.",
  "Tap Create exercise when it looks right. Or Next to just look around.": "Tryck på Skapa övning när det ser rätt ut. Eller Nästa för att bara titta runt.",
  "Tap New routine. It stays a draft until you save it.": "Tryck på Ny rutin. Den är ett utkast tills du sparar den.",
  "Tap Schedule to put it on a day.": "Tryck på Schema för att lägga den på en dag.",
  "Tap a weekday and choose your new routine. Two on one day works too.": "Tryck på en veckodag och välj din nya rutin. Två på samma dag funkar också.",
  "Tap an exercise any time to change sets, reps or weight. The arrows reorder, the link makes a superset.": "Tryck på en övning när som helst för att ändra set, reps eller vikt. Pilarna ändrar ordning, länken gör ett superset.",
  "Tap back to Settings.": "Tryck tillbaka till Inställningar.",
  "Tap back.": "Tryck tillbaka.",
  "Tap it.": "Tryck på den.",
  "Tap one to set its sets, reps and weight, or + to take the usual. Close the list when you’re done.": "Tryck på en för att ställa in set, reps och vikt, eller + för det vanliga. Stäng listan när du är klar.",
  "That’s a plan": "Där är en plan",
  "That’s the lot": "Det var allt",
  "The bin deletes one, and Undo pops up right after. Wrong number? Log that day again and the new one wins.": "Papperskorgen tar bort en, och Ångra dyker upp direkt efter. Fel siffra? Logga den dagen igen så vinner den nya.",
  "The exercise library": "Övningsbiblioteket",
  "The gear": "Kugghjulet",
  "The phone saves a fresh backup by itself after changes.": "Telefonen sparar en färsk backup själv efter ändringar.",
  "They live under Stats. Tap it.": "De bor under Statistik. Tryck på den.",
  "They’re on Home. Tap it.": "De finns på Hem. Tryck på det.",
  "This is your real plan now, if you want it. Save keeps it. Skip and it was never here.": "Det här är din riktiga plan nu, om du vill ha den. Spara behåller den. Hoppa över så har den aldrig funnits.",
  "This one is for real: we build a routine together and it lands in your plan when you tap Save. Bail before that and nothing stays behind.": "Den här är på riktigt: vi bygger en rutin tillsammans och den hamnar i din plan när du trycker på Spara. Hoppar du av innan blir inget kvar.",
  "Tutorials": "Guider",
  "Up one level": "Upp en nivå",
  "Want more? Each of these is a short guided run. You’ll find them again in Settings → About & updates.": "Vill du ha mer? Var och en är en kort guidad tur. Du hittar dem igen under Inställningar → Om och uppdateringar.",
  "We swapped in a practice copy with a pretend workout and weigh-in. Poke at anything, nothing here sticks.": "Vi bytte in en övningskopia med ett låtsaspass och en låtsasvägning. Peta på vad du vill, inget här sparas.",
  "Weigh-ins first": "Vägningar först",
  "Weight unit, plates and stack live here. Edit or delete the exercise from here too.": "Viktenhet, skivor och vikttorn finns här. Redigera eller ta bort övningen härifrån också.",
  "What you can’t edit": "Det du inte kan redigera",
  "When do you train it?": "När tränar du den?",
  "Where your data goes in and out. We only point, nothing runs until you tap it yourself.": "Här går din data in och ut. Vi pekar bara, inget körs förrän du själv trycker.",
  "Workouts, weigh-ins and what can be fixed": "Pass, vägningar och vad som går att rätta",
  "Your data, your call. Back it up now and then, future you will be grateful.": "Din data, ditt beslut. Säkerhetskopiera då och då, framtida du kommer att vara tacksam.",
  "Your numbers": "Dina siffror",
  "Your own exercise": "Din egen övning",
  "Your own server": "Din egen server",
  "Your real data is exactly as you left it.": "Din riktiga data är exakt som du lämnade den.",
  "Your routines live behind this tab. Tap Plan.": "Dina rutiner bor bakom den här fliken. Tryck på Plan.",
  "Your sets, weigh-ins and measurements as CSV. Our importer reads it back too.": "Dina set, vägningar och mått som CSV. Vår import läser in det igen också.",
  "Date, duration, share, export, delete": "Datum, tid, dela, exportera, ta bort",
  "Rewrite the session note whenever.": "Skriv om passets anteckning när du vill.",
  "Wrong day or forgot to finish on time? Fix it in here. Sharing, export and Delete live here too.": "Fel dag eller glömde avsluta i tid? Fixa det här inne. Dela, exportera och Ta bort pass bor också här.",
