  "That workout is over, so these can’t be applied any more.": "Det passet är slut, så de här går inte att använda längre.",
  "The app ramps up from your work weight: more warm-up sets when it is heavy, fewer when it is light, on your gym’s plates.": "Appen bygger upp från din arbetsvikt: fler uppvärmningsset när det är tungt, färre när det är lätt, med ditt gyms viktskivor.",
  "The rack is taken, so do it at the end. The rest of the session does not need it.": "Racket är upptaget, så gör det sist. Resten av passet behöver det inte.",
  "There’s no workout running.": "Inget pass pågår.",
  "These warm-ups come before the work sets every session, as a share of the work weight, so they grow with it.": "Den här uppvärmningen kommer före arbetsseten varje pass, som andel av arbetsvikten, så den växer med den.",
  "This is the demo, so there is no AI model behind me. On your own server I read your session and suggest changes like these.": "Det här är demot, så det finns ingen AI-modell bakom mig. På din egen server läser jag ditt pass och föreslår ändringar som dessa.",
