  "The sharing text changed. Have a quick read and try again.": "Delningstexten har ändrats. Läs igenom den snabbt och försök igen.",
  "This is public to everyone on this server: everyone with an account here can see it, try it and copy it. Your name and the date go with it, always. Only share what is yours: something you made, recorded or have the right to pass on. The exercise pictures and animations of the built-in library are licensed and can never be shared. You can stop sharing any time; copies people already took stay with them.": "Det här är offentligt för alla på den här servern: alla med ett konto här kan se det, testa det och kopiera det. Ditt namn och datumet följer alltid med. Dela bara det som är ditt: något du har gjort, spelat in eller har rätt att föra vidare. Övningsbilderna och animationerna i det inbyggda biblioteket är licensierade och kan aldrig delas. Du kan sluta dela när du vill; kopior som andra redan har hämtat stannar hos dem.",
