  "Your exercises can move at {0} px instead of {1} px, crisp on this screen.": "Dina övningar kan röra sig i {0} px i stället för {1} px, knivskarpt på den här skärmen.",
  "A one-time download of about {0} from Google Play, over Wi-Fi. It stays on this phone.": "En engångsnedladdning på cirka {0} från Google Play, via wifi. Den stannar på den här telefonen.",
  "A one-time download from Google Play, over Wi-Fi. It stays on this phone.": "En engångsnedladdning från Google Play, via wifi. Den stannar på den här telefonen.",
  "Download": "Ladda ned",
  "Changed your mind? Settings has it, any time.": "\u00c5ngrat dig? Det finns i Inst\u00e4llningar, n\u00e4r som helst.",
  "A profile here already uses that e-mail. Sign in to it another way, then link {0} in Settings.": "En profil här använder redan den e-postadressen. Logga in på den på annat sätt och koppla sedan {0} i Inställningar.",
  "Admin? Use your passkey": "Admin? Använd din passkey",
  "Confirm with {0}": "Bekräfta med {0}",
  "Confirmed. Go ahead.": "Bekräftat. Kör.",
  "Link": "Koppla",
  "Link your {0} account and sign in with it from now on. Your passkeys keep working too. First a quick check that this is really you.": "Koppla ditt {0}-konto och logga in med det från och med nu. Dina passkeys fortsätter att fungera. Först en snabb koll att det verkligen är du.",
  "Linked. You can sign in with {0} from now on.": "Kopplat. Nu kan du logga in med {0}.",
  "Linked. {0} signs you in here.": "Kopplat. {0} loggar in dig här.",
