  "Sign in with your provider again first, then try once more.": "Logga in hos din leverantör igen först och försök sedan en gång till.",
  "Sign in with {0}": "Logga in med {0}",
  "Sign-in cancelled. No harm done.": "Inloggningen avbröts. Ingen skada skedd.",
  "That sign-in took too long or came from another tab. Give it another go.": "Den inloggningen tog för lång tid eller kom från en annan flik. Försök igen.",
  "That was a different {0} account than the one linked to this profile.": "Det var ett annat {0}-konto än det som är kopplat till den här profilen.",
  "That {0} account is already linked to another profile here.": "Det {0}-kontot är redan kopplat till en annan profil här.",
  "This profile is already linked to a {0} account.": "Den här profilen är redan kopplad till ett {0}-konto.",
  "This profile is linked to your {0} account, so signing in there signs you in here.": "Den här profilen är kopplad till ditt {0}-konto: inloggad där, inloggad här.",
  "This server is invite-only and {0} alone does not get you in. Ask whoever runs it.": "Den här servern kräver inbjudan och {0} räcker inte ensamt. Fråga den som driver den.",
  "This server signs everyone in with {0}. New here? Signing in makes your profile.": "På den här servern loggar alla in med {0}. Ny här? Inloggningen skapar din profil.",
  "This server signs people in with {0}.": "Den här servern loggar in folk med {0}.",
  "Too many attempts. Try again in a minute.": "För många försök. Försök igen om en minut.",
  "Unlink": "Koppla bort",
  "Unlinked. {0} no longer signs you in here.": "Bortkopplat. {0} loggar inte längre in dig här.",
  "or use a pairing code": "eller använd en parkopplingskod",
  "{0} could not be reached. Try again in a moment.": "Det gick inte att nå {0}. Försök igen om en stund.",
  "{0} is the only way into this profile, so it stays linked. Add a passkey first.": "{0} är den enda vägen in i den här profilen, så den förblir kopplad. Lägg till en passkey först.",
  "{0} let you in, but this server only takes certain groups. Ask whoever runs it to add you.": "{0} släppte in dig, men den här servern tar bara vissa grupper. Be den som driver den att lägga till dig.",
  "{0} sent back something we could not verify, so nobody was signed in. If it keeps happening, the admin page shows why.": "{0} skickade tillbaka något vi inte kunde verifiera, så ingen loggades in. Händer det igen visar adminsidan varför.",
  "Backups: {0}": "Reserver: {0}",
  "Suggested": "Förslag",
  "Add “{0}” as a backup": "Lägg till ”{0}” som reserv",
  "Ask the Coach for a swap": "Fråga coachen om ett byte",
