  "Separate numbers per gym": "Separata siffror per gym",
  "Last time and the next weight come from this gym only.": "Förra gången och nästa vikt hämtas bara från det här gymmet.",
  "Brand at {0}": "Märke på {0}",
  "Life Fitness, Technogym… (optional)": "Life Fitness, Technogym… (valfritt)",
  "Same brand at another gym? It shares these numbers. Records and Stats still count every gym.": "Samma märke på ett annat gym? Då delar det de här siffrorna. Rekord och statistik räknar fortfarande alla gym.",
  "For machines and cables that feel different from gym to gym. Free weights rarely need it.": "För maskiner och kablar som känns olika från gym till gym. Fria vikter behöver det sällan.",
  "All gyms": "Alla gym",
  "Today’s planned rows for {0} didn’t fit, so the routine’s own are up: {1}": "De planerade seten för {0} passade inte, så rutinens egna gäller: {1}",
  "Today’s rows come from {0}. Your routine stays as it is.": "Dagens set kommer från {0}. Din rutin är som den var.",
  "Today’s rows were planned for this day. Your routine stays as it is.": "Dagens set planerades för den här dagen. Din rutin är som den var.",
  "Body composition from your scale": "Kroppssammansättning från din våg",
  "Body fat and lean mass, as your scale saved them. Shown under Body measurements, never mixed into what you log.": "Kroppsfett och fettfri massa, så som din våg sparade dem. Visas under Kroppsmått och blandas aldrig med det du loggar.",
  "Body fat, lean mass, bone mass, body water and BMR, as your scale saved them. Shown under Body measurements, never mixed into what you log.": "Kroppsfett, fettfri massa, benmassa, kroppsvatten och basalmetabolism, så som din våg sparade dem. Visas under Kroppsmått och blandas aldrig med det du loggar.",
