  // --- API tokens and MCP over HTTPS (mcp-146) ---
  "You made the token {0}": "Du skapade token {0}",
  "The token {0} was revoked": "Token {0} återkallades",
  "The token {0} changed {1}": "Token {0} ändrade {1}",
  "A token lets one program, like an AI assistant, see or change only what you tick. Never more than you can, and only your own profile.": "En token låter ett program, som en AI-assistent, se eller ändra bara det du bockar för. Aldrig mer än du själv får, och bara din egen profil.",
  "API token": "API-token",
  "API tokens": "API-tokens",
  "Add it as a custom connector in your AI assistant, with a token from below.": "Lägg till den som egen connector i din AI-assistent, med en token nedanför.",
  "After a year": "Efter ett år",
  "After {0} days": "Efter {0} dagar",
  "Copy it now: this is the only time openGym shows it. Treat it like a password.": "Kopiera den nu: det är enda gången openGym visar den. Behandla den som ett lösenord.",
  "Ends": "Slutar",
  "Every program using one stops getting in right away.": "Varje program som använder en kommer inte in längre, direkt.",
