  "A buzz for each phase": "En vibration för varje fas",
  "A copy of everything, once a day, in a folder of your own: Nextcloud, ownCloud, a NAS, anything that speaks WebDAV. Your server, nobody else’s.": "En kopia av allt, en gång om dagen, i en egen mapp: Nextcloud, ownCloud, en NAS, vad som helst som pratar WebDAV. Din server, ingen annans.",
  "A sound for each kind of rest": "Ett ljud för varje sorts vila",
  "A tick on every day you trained, with how many sets. Only you see it, the same as the plan.": "En bock för varje dag du tränat, med antal set. Bara du ser den, precis som planen.",
