  "Backed up to {0}": "Säkerhetskopierat till {0}",
  "Calendar feed": "Kalenderflöde",
  "Calendar feed off": "Kalenderflöde av",
  "Cardio goes up as what it was: a run, a ride, a row. Strength as Weight Training, with every set in the description.": "Kondition laddas upp som det var: en löprunda, en cykeltur, en roddtur. Styrka som Styrketräning, med varje set i beskrivningen.",
  "Change server or password": "Byt server eller lösenord",
  "Check the connection": "Kontrollera anslutningen",
  "Connect Strava once from openGym in a browser, signed in to your server. Your workouts then go up from the server, whichever device you log them on.": "Anslut Strava en gång från openGym i en webbläsare, inloggad på din server. Sedan laddas dina pass upp från servern, oavsett vilken enhet du loggar dem på.",
  "Connected. Your first backup goes up now.": "Ansluten. Din första säkerhetskopia laddas upp nu.",
  "Disconnect Strava?": "Koppla från Strava?",
  "Disconnect WebDAV?": "Koppla från WebDAV?",
  "Explosive lift (X)": "Explosivt lyft (X)",
  "Folder address": "Mappadress",
  "Get set": "Redo",
  "Know from your pocket whether to stay put, go back to the top of the superset or move on.": "Vet direkt från fickan om du ska stanna kvar, gå tillbaka till början av supersetet eller gå vidare.",
  "Last backup {0}": "Senaste säkerhetskopia {0}",
  "Last fetched by a calendar {0}": "Senast hämtad av en kalender {0}",
