  "Leave empty to keep the one saved": "Lämna tomt för att behålla det sparade",
  "Like 3-1-1-0: three seconds down, one at the bottom, one up.": "Som 3-1-1-0: tre sekunder ner, en i botten, en upp.",
  "Like the exercise ({0})": "Som övningen ({0})",
  "Link copied. Paste it into your calendar app.": "Länken kopierad. Klistra in den i din kalenderapp.",
  "Make a new link": "Skapa en ny länk",
