  "Make my calendar link": "Skapa min kalenderlänk",
  "New link made. The old one is gone.": "Ny länk skapad. Den gamla är borta.",
  "Nextcloud or any WebDAV folder, once a day": "Nextcloud eller valfri WebDAV-mapp, en gång om dagen",
  "No backup yet": "Ingen säkerhetskopia än",
  "No calendar has fetched it yet.": "Ingen kalender har hämtat den än.",
  "No openGym backups in that folder yet.": "Inga openGym-säkerhetskopior i den mappen än.",
  "No tempo": "Inget tempo",
  "Open in my calendar app": "Öppna i min kalenderapp",
  "Pick one. You choose whether it replaces what is here or merges with it.": "Välj en. Du bestämmer om den ersätter det som finns här eller slås ihop med det.",
  "Reconnect": "Anslut igen",
  "Rep {0} of {1}": "Rep {0} av {1}",
  "Restore from a backup": "Återställ från en säkerhetskopia",
  "Same as the rest ({0})": "Samma som resten ({0})",
  "Seconds for each part of a rep: lower, pause, lift, squeeze. 3-1-1-0 is three down, one at the bottom, one up, straight into the next.": "Sekunder för varje del av en rep: sänk, paus, lyft, kläm. 3-1-1-0 är tre ner, en i botten, en upp, direkt in i nästa.",
  "Show finished workouts too": "Visa även avslutade pass",
  "Strava connected. Your next workout goes up by itself.": "Strava anslutet. Ditt nästa pass laddas upp av sig självt.",
  "Strava disconnected": "Strava frånkopplat",
  "Strava is listening": "Strava lyssnar",
  "Strava is off on this server. Register a Strava API app, then add strava to INTEGRATIONS and its STRAVA_CLIENT_ID and STRAVA_CLIENT_SECRET to the .env, and restart.": "Strava är avstängt på den här servern. Registrera en Strava API-app, lägg sedan till strava i INTEGRATIONS och dess STRAVA_CLIENT_ID och STRAVA_CLIENT_SECRET i .env, och starta om.",
  "Strava uploads come from your own openGym server, so they need one. Connect this device to it in Account.": "Uppladdningar till Strava kommer från din egen openGym-server, så du behöver en. Anslut den här enheten till den under Konto.",
  "Strength workouts too": "Styrkepass också",
  "Subscribe to this link in your calendar app. Anyone with it sees your plan, so keep it to yourself.": "Prenumerera på den här länken i din kalenderapp. Alla som har den ser din plan, så håll den för dig själv.",
  "Tempo": "Tempo",
  "Tempo for this set": "Tempo för det här setet",
  "Tempo {0}": "Tempo {0}",
  "Tempo {0}, start the guide": "Tempo {0}, starta guiden",
  "The calendar link is served by your own openGym server, so it needs one. Connect this device to it in Account.": "Kalenderlänken kommer från din egen openGym-server, så du behöver en. Anslut den här enheten till den under Konto.",
  "The link stops working at once. What your calendar already shows may stay until it refreshes.": "Länken slutar fungera direkt. Det din kalender redan visar kan ligga kvar tills den uppdateras.",
  "The old link stops working, and every calendar that uses it needs the new one.": "Den gamla länken slutar fungera, och varje kalender som använder den behöver den nya.",
  "The password stays on this device, in its secure storage. It is never synced or put in a backup.": "Lösenordet stannar på den här enheten, i dess säkra lagring. Det synkas aldrig och hamnar aldrig i en säkerhetskopia.",
  "The server cannot show this link again. Make a new one.": "Servern kan inte visa den här länken igen. Skapa en ny.",
  "This device stops backing up and forgets the password. The backups already in the folder stay there.": "Den här enheten slutar säkerhetskopiera och glömmer lösenordet. Säkerhetskopiorna som redan ligger i mappen stannar där.",
  "Tick the set": "Bocka av setet",
  "Turn off": "Stäng av",
  "Turn off the calendar feed?": "Stänga av kalenderflödet?",
  "Up as fast as you can. The guide gives it one quick second.": "Upp så snabbt du kan. Guiden ger det en snabb sekund.",
  "Uploading": "Laddar upp",
  "User name": "Användarnamn",
  "WebDAV backup": "WebDAV-säkerhetskopia",
  "When the app is open, at most once a day, on this device.": "När appen är öppen, högst en gång om dagen, på den här enheten.",
  "Your planned sessions in Apple Calendar, Google Calendar or Outlook, kept up to date. A private link only your calendar knows.": "Dina planerade pass i Apple Calendar, Google Calendar eller Outlook, alltid uppdaterade. En privat länk som bara din kalender känner till.",
  "Your server forgets the sign-in and stops uploading. What is on Strava stays, and the Strava app keeps its access until you remove it on strava.com.": "Din server glömmer inloggningen och slutar ladda upp. Det som finns på Strava blir kvar, och Strava-appen behåller sin åtkomst tills du tar bort den på strava.com.",
  "{0} s per rep, a guide in the workout counts it for you.": "{0} s per rep, en guide i passet räknar åt dig.",
  "{0} s under tension": "{0} s under spänning",
  "{0} s under tension. Lovely and slow.": "{0} s under spänning. Härligt långsamt.",
  "Backups & calendar": "Säkerhetskopior och kalender",
  "A copy every day in your own Nextcloud or any WebDAV folder.": "En kopia varje dag i ditt eget Nextcloud eller valfri WebDAV-mapp.",
  "The full backup, once a day while the app is open, and whenever you tap Back up now.": "Hela säkerhetskopian, en gång om dagen när appen är öppen, och varje gång du trycker på Säkerhetskopiera nu.",
  "Restore it on a new phone in two taps.": "Återställ den på en ny telefon med två tryck.",
  "Your planned sessions in Apple, Google or Outlook calendar.": "Dina planerade pass i Apple-, Google- eller Outlook-kalendern.",
  "Planned sessions from a week back to eight weeks ahead, as all-day events.": "Planerade pass från en vecka bakåt till åtta veckor framåt, som heldagshändelser.",
  "Finished workouts too, if you like.": "Avslutade pass också, om du vill.",
  "Your runs, rides and rows go up to Strava, strength too if you like.": "Dina löprundor, cykelturer och roddpass hamnar på Strava, styrka också om du vill.",
  "Finished cardio workouts, with their time and distance.": "Avslutade konditionspass, med tid och distans.",
  "Strength sessions as Weight Training, if you switch it on.": "Styrkepass som Styrketräning, om du slår på det.",
  "After a warm-up set": "Efter ett uppvärmningsset",
  "The ramp is still going.": "Uppvärmningen pågår fortfarande.",
  "Between working sets": "Mellan arbetsset",
