  "Lift (s)": "Lyft (s)",
  "Squeeze at the top (s)": "Kläm i toppen (s)",
  "The server did not take that name and password. An app password usually works best.": "Servern godtog inte det namnet och lösenordet. Ett applösenord brukar fungera bäst.",
  "That folder is not there, and openGym could not make it. Make it on the server first.": "Den mappen finns inte, och openGym kunde inte skapa den. Skapa den på servern först.",
  "The server says this account may not write there.": "Servern säger att det här kontot inte får skriva där.",
  "The server is out of space for this account.": "Servern har slut på utrymme för det här kontot.",
  "Could not reach the server. In a browser it also has to allow this site (CORS), see the guide.": "Kunde inte nå servern. I en webbläsare måste den också tillåta den här sajten (CORS), se guiden.",
  "Type the password again: this device does not have it.": "Skriv lösenordet igen: den här enheten har det inte.",
  "That file is not an openGym backup.": "Den filen är ingen openGym-säkerhetskopia.",
  "Nothing to back up yet: log a workout first.": "Inget att säkerhetskopiera än: logga ett pass först.",
  "The server answered with an error.": "Servern svarade med ett fel.",
  "Paste the address of the folder on your WebDAV server.": "Klistra in adressen till mappen på din WebDAV-server.",
  "That does not look like an address.": "Det där ser inte ut som en adress.",
  "Leave the name and password out of the address, they have their own fields.": "Låt namn och lösenord stå utanför adressen, de har egna fält.",
  "Strava was not given access. Nothing was connected.": "Strava fick ingen åtkomst. Inget anslöts.",
  "Strava has to be allowed to upload activities. Connect again and leave that box ticked.": "Strava måste få ladda upp aktiviteter. Anslut igen och låt den rutan vara ikryssad.",
  "That sign-in took too long or came from somewhere else. Start again from here.": "Den inloggningen tog för lång tid eller kom från något annat ställe. Börja om härifrån.",
