  "Shorter rests": "Kortare vila",
  "Work up a rep range one rep at a time. Every set has to hit the target before it moves, and at the top of the range the weight goes up.": "Jobba dig upp genom ett repsintervall en rep i taget. Varje set måste nå målet innan det flyttas, och högst upp i intervallet ökar vikten.",
  "Each session rotates: a medium day at your reps, a heavy day with fewer, a light day with more. The weights come from your estimated max, so they climb as you get stronger.": "Varje pass växlar: en medeldag med dina reps, en tung dag med färre, en lätt dag med fler. Vikterna kommer från ditt uppskattade max, så de stiger när du blir starkare.",
  "Same weight, a bit less rest each time every set is clean. At your shortest rest the weight goes up and the rest starts over.": "Samma vikt, lite mindre vila varje gång alla set är rena. Vid din kortaste vila ökar vikten och vilan börjar om.",
  "Every set hit {0}. Same weight, {1} reps this time.": "Varje set klarade {0}. Samma vikt, {1} reps den här gången.",
  "Not every set reached {0} yet. Same weight and target again ({1} of {2} to go).": "Inte alla set har nått {0} än. Samma vikt och mål igen ({1} av {2} kvar).",
  "Every set clean. Same weight with {0}s less rest: {1}s.": "Alla set rena. Samma vikt med {0} s kortare vila: {1} s.",
  "Clean at your shortest rest. {0} {1} less help, rest back to {2}s.": "Rent på din kortaste vila. {0} {1} mindre hjälp, vilan tillbaka till {2} s.",
  "Clean at your shortest rest. {0} {1} more, rest back to {2}s.": "Rent på din kortaste vila. {0} {1} mer, vilan tillbaka till {2} s.",
  "Stuck for {0} sessions. Same weight with more rest: {1}s.": "Fast i {0} pass. Samma vikt med mer vila: {1} s.",
  "Missed reps last time. Same weight and rest again ({0} of {1} to go).": "Missade reps förra gången. Samma vikt och vila igen ({0} av {1} kvar).",
  "Heavy day: {0} reps at {1} {2}, from your estimated max of {3} {2}.": "Tung dag: {0} reps på {1} {2}, utifrån ditt uppskattade max på {3} {2}.",
  "Light day: {0} reps at {1} {2}, from your estimated max of {3} {2}.": "Lätt dag: {0} reps på {1} {2}, utifrån ditt uppskattade max på {3} {2}.",
