  "openGym asks Apple Health for your sleep, resting heart rate, heart rate variability and steps. Allow the ones you like. They stay on this phone, in openGym’s own file, and never go to a server.": "openGym ber Apple Health om din sömn, vilopuls, pulsvariabilitet och dina steg. Tillåt de du vill. De stannar på den här telefonen, i openGyms egen fil, och skickas aldrig till en server.",
