  "If nobody answers, it finishes by itself and never throws anything away. The end is your last set plus its rest, so the time stays honest. Reopen it from History for a day. Your watch asks too.": "Om ingen svarar avslutas det av sig självt och inget slängs någonsin. Slutet är ditt sista set plus dess vila, så tiden förblir ärlig. Öppna det igen från historiken i ett dygn. Klockan frågar också.",
  "Never asks and never ends one by itself.": "Frågar aldrig och avslutar aldrig något av sig självt.",
  "The default. Long enough for a chat at the water fountain.": "Standard. Lagom för ett snack vid vattenautomaten.",
  "Asks the moment your phone walks out of your gym, then wraps up.": "Frågar så fort telefonen promenerar ut från ditt gym, och avslutar sedan.",
  "Needs the gym reminder: {0}.": "Kräver gympåminnelsen: {0}.",
  "Save to Photos": "Spara i Bilder",
  "Save image": "Spara bild",
  "Saved to Photos": "Sparad i Bilder",
  "Could not save the picture.": "Det gick inte att spara bilden.",
  "openGym may not add pictures to Photos. You can allow it in the phone settings.": "openGym får inte lägga till bilder i Bilder. Du kan tillåta det i telefonens inställningar.",
  // --- the live widget builder (session-widgets-146) ---
  "A preset sets every surface. Then change whatever you like.": "En mall ställer in varje yta. Ändra sedan vad du vill.",
  "Add a button": "Lägg till en knapp",
  "Add a tile": "Lägg till en ruta",
  "Android": "Android",
  "Android allows three buttons on a notification. Three it is.": "Android tillåter tre knappar i en notis. Tre får det bli.",
  "As many as you like. They wrap onto new rows.": "Så många du vill. De bryts till nya rader.",
  "Buttons": "Knappar",
  "Dynamic Island": "Dynamic Island",
  "Four buttons fit on the Lock Screen.": "Fyra knappar får plats på låsskärmen.",
  "Home Screen widget": "Widget på hemskärmen",
  "In the app": "I appen",
  "Lifter": "Styrka",
  "Live widget": "Livewidget",
  "Lock Screen": "Låsskärm",
  "Lock Screen, notification, the workout card": "Låsskärm, notis, passets kort",
  "Long-press view": "Vy vid långt tryck",
  "Minimal": "Minimal",
  "Needs iOS 17 or later. No animations on the Lock Screen, so the exercise picture is a still. Buttons work without unlocking, Finish opens the app.": "Kräver iOS 17 eller senare. Inga animationer på låsskärmen, så övningsbilden är stilla. Knapparna fungerar utan att låsa upp, Avsluta öppnar appen.",
  "No buttons. A tap on it opens openGym.": "Inga knappar. Ett tryck öppnar openGym.",
  "No room on the Lock Screen. Apple keeps Live Activities to about 160 points tall.": "Ingen plats kvar på låsskärmen. Apple håller liveaktiviteter runt 160 punkter höga.",
  "No tiles yet.": "Inga rutor än.",
  "Nothing here yet, so the workout screen stays as it is. Add a tile or pick a preset.": "Här finns inget än, så träningsskärmen är som den är. Lägg till en ruta eller välj en mall.",
  "Opens openGym, since saving asks what to keep.": "Öppnar openGym, eftersom sparandet frågar vad som ska behållas.",
  "Six tiles fit in a notification before it starts mumbling.": "Sex rutor får plats i en notis innan den börjar mumla.",
  "Size of {0}": "Storlek på {0}",
  "The Dynamic Island holds four tiles. It is an island, not a continent.": "Dynamic Island rymmer fyra rutor. Det är en ö, inte en kontinent.",
  "The pill": "Pillret",
  "The pill has two spots, one each side of the camera.": "Pillret har två platser, en på var sida om kameran.",
  "The pill shows two tiles beside the camera. Long-press it for the rest.": "Pillret visar två rutor bredvid kameran. Tryck länge för resten.",
  "The widget fits three lines under the set.": "Widgeten rymmer tre rader under setet.",
  "Three buttons fit in the Dynamic Island.": "Tre knappar får plats i Dynamic Island.",
  "Tiles": "Rutor",
  "Tiles become lines of text, so Android 16 can keep it a Live Update by the clock. While a rest runs, the notification shows its rest buttons.": "Rutorna blir textrader, så att Android 16 kan behålla den som Live Update vid klockan. Under en vila visar notisen sina vilknappar.",
  "Up to three lines under the set. The widget keeps its own − and + buttons.": "Upp till tre rader under setet. Widgeten behåller sina egna − och + knappar.",
  "Where it shows": "Var den visas",
