  "Add it as a custom connector in Claude or ChatGPT and sign in with openGym when it asks. Other assistants take a token from below.": "Lägg till den som egen anslutning i Claude eller ChatGPT och logga in med openGym när den frågar. Andra assistenter tar en token här nedanför.",
  "Add “{0}” to my plan": "Lägg till ”{0}” i min plan",
