  "Code from OpenRouter": "Kod från OpenRouter",
  "Daily check-ins, sleep, resting heart rate, HRV and steps from your phone, and blood pressure. Off until you switch it on.": "Dagliga incheckningar, sömn, vilopuls, HRV och steg från mobilen samt blodtryck. Av tills du slår på det.",
