  "How it’s done": "Så görs den",
  "It shows up under Settings → API tokens, where you can revoke it any time.": "Den syns under Inställningar → API-token, där du kan återkalla den när som helst.",
  "Looks for Ollama, LM Studio and llama.cpp on the machine running your openGym server and on this phone.": "Letar efter Ollama, LM Studio och llama.cpp på datorn med din openGym-server och på den här mobilen.",
  "Nothing answered. Type its address below, like http://192.168.1.20:11434.": "Inget svarade. Skriv adressen nedan, till exempel http://192.168.1.20:11434.",
  "Ollama or LM Studio at home, nothing leaves your Wi-Fi": "Ollama eller LM Studio hemma, inget lämnar ditt wifi",
  "On my network": "I mitt nätverk",
  "One sign-in for Claude, GPT, Gemini and more": "En inloggning för Claude, GPT, Gemini och fler",
  "OpenRouter makes a key just for this phone, billed to your OpenRouter credits. You can revoke it there any time.": "OpenRouter gör en nyckel bara för den här mobilen, som dras från dina OpenRouter-krediter. Du kan återkalla den där när som helst.",
